mapper.insert:
INSERT INTO material_text_units (
    user_id, material_id, file_hash, unit_index, unit_type, unit_no, char_count, text
) VALUES (
    #{userId}, #{materialId}, #{fileHash}, #{unitIndex}, #{unitType}, #{unitNo}, #{charCount}, #{text}
)

mapper.select:
SELECT * FROM material_text_units
WHERE material_id = #{materialId} AND file_hash = #{fileHash}
ORDER BY unit_index ASC

SELECT unitId, materialId, unitIndex, unitType, unitNo, charCount, hits FROM (
    SELECT h.*, ROW_NUMBER() OVER (PARTITION BY h.materialId ORDER BY h.hits DESC, h.unitIndex ASC) AS rn
    FROM (
        SELECT unit_id AS unitId, material_id AS materialId, unit_index AS unitIndex, unit_type AS unitType,
               unit_no AS unitNo, char_count AS charCount,
               ((CASE WHEN text LIKE CONCAT('%', #{t}, '%') OR REPLACE(text, ' ', '') LIKE CONCAT('%', #{t}, '%') THEN 1 ELSE 0 END)) AS hits
        FROM material_text_units
        WHERE user_id = #{userId}
          AND ((material_id = #{m.materialId} AND file_hash = #{m.fileHash}))
    ) h
    WHERE h.hits > 0
) ranked
WHERE rn <= #{perMaterial}
ORDER BY hits DESC, materialId ASC, unitIndex ASC
LIMIT #{limit}

SELECT * FROM material_text_units
WHERE user_id = #{userId}
  AND unit_id IN #{id}
ORDER BY material_id ASC, unit_index ASC

SELECT * FROM material_text_units
WHERE user_id = #{userId} AND material_id = #{materialId} AND file_hash = #{fileHash}
  AND unit_no BETWEEN #{unitFrom} AND #{unitTo}
ORDER BY unit_index ASC
